"""Whole complete impact tester and raised dual-column frame on separate floor and open bridge bench; exact full-original GLB payload preservation."""
import base64,copy,hashlib,json,math,struct,zlib
from pathlib import Path
ASSET='industrial-whole-impact-tester-and-raised-dual-column-frame-preparation-bay-scene-01'
TITLE='Whole Impact Tester and Raised Dual Column Frame Preparation Bay'
DESCRIPTION='One newly authored empty materials-instrument preparation bay scene, zero new independent models and one scene. The complete accepted pendulum-impact-tester exterior stands on the left common floor, retaining its entire broad ground sole, twin buttressed standards, upper bearings and crossshaft, full long arm and hammer, two low separated anvils, whole offset dial and all retainers unchanged. The complete accepted twin-guide-column test-frame exterior stands separately on a right raised bridge bench, retaining its whole console base, both complete round guides, upper bridge, through-bored sleeve crosshead, opposed empty grip cases and jaws, every adjuster and blank panel unchanged. One new continuous thick inverted-U scene-only bench has two broad finite feet and a genuinely open rectangular under-bench passage; one common finite rectangular floor supports both the full impact tester sole and both full bench feet. Whole-unit wrappers translate only at exact binary-fraction offsets: no scaling, rotation, local edits, removed parts or fragment extraction. Complete original binary geometry payloads, normals, PBR dictionaries and internal node transformations preserved byte-for-byte. Instruments are distinct and separated without touching each other; their top heights align approximately through the raised support rather than changing model size. Unlike the earlier core-drill/yoke scene there is no continuous multi-level stepped terrace. This is a left floor-standing tall instrument plus a separate right through-arch bench and complete smaller axial frame, with an empty central separation. No specimen, actual impact, tension, measured force, strain, accuracy, calibration, inspection procedure, loading, construction, workflow simulation, engineering or safety capability made or verified. No rigging, animation, physics or interaction.'
TOL=2e-7
OFFSETS={'impact': (-0.8125, 0, 0.0625), 'frame': (0.8125, 0.1875, 0.5625)}
ROTATIONS={'impact': (1, 0), 'frame': (1, 0)}
INPUTS={'impact': {'sha256': '851c982692fd47f35cbec17aa02ca0afeb2cf2a5d0319dec1e99731ce28f3eb6', 'compressed': ''}, 'frame': {'sha256': '11d7443ec55a4e988e7ff7b9cc78ed37dbb8671de4e85a5ac11db0abd1ffc640', 'compressed': ''}}
SOURCE_INPUTS={'impact': {'sha256': '0aca798a5c6a37c91702f6143d70997f762e0818e50321f365aa9fdda2c5ee0a', 'compressed': ''}, 'frame': {'sha256': '288dcfa1ba3cdb0789bb7b0ccaa1217c8f43a8e39a5fe10e5de4e2f54964ac3c', 'compressed': ''}}
def f32(x):return struct.unpack('<f',struct.pack('<f',x))[0]
def wrapper_matrix(key):
 # Exact determinant +1 signed permutation in glTF Y-up, column-major.
 # No quaternion, data baking, normal setter or simultaneous node TRS.
 c,s=ROTATIONS[key];x,y,z=OFFSETS[key]
 return [c,0,-s,0,0,1,0,0,s,0,c,0,f32(x),f32(z),f32(-y),1]
def unpack_glb(raw):
 magic,version,size=struct.unpack_from('<4sII',raw);assert magic==b'glTF' and version==2 and size==len(raw)
 n,kind=struct.unpack_from('<II',raw,12);assert kind==0x4e4f534a
 doc=json.loads(raw[20:20+n]);p=20+n;length,kind=struct.unpack_from('<II',raw,p);assert kind==0x004e4942
 blob=raw[p+8:p+8+length];assert len(blob)==length and len(doc['buffers'])==1
 assert doc['buffers'][0]['byteLength']<=len(blob)
 return doc,blob

def pack_glb(doc,blob):
 j=json.dumps(doc,separators=(',',':'),allow_nan=False).encode();j+=b' '*((-len(j))%4)
 b=bytes(blob)+b'\0'*((-len(blob))%4)
 return struct.pack('<4sII',b'glTF',2,12+8+len(j)+8+len(b))+struct.pack('<II',len(j),0x4e4f534a)+j+struct.pack('<II',len(b),0x004e4942)+b

def compose(inputs):
  d=dict(asset={'version':'2.0','generator':'Source-preserving static scene composition'},scene=0,scenes=[{'name':TITLE,'nodes':[0]}],nodes=[{'name':'AssetRoot__'+ASSET,'children':[]}],meshes=[],materials=[],accessors=[],bufferViews=[],buffers=[])
  blob=bytearray();proof={}
  for key in ['impact','frame']:
    raw=inputs[key];src,b=unpack_glb(raw)
    assert not any(src.get(x) for x in ['textures','images','skins','animations','cameras','extensionsUsed','extensionsRequired'])
    assert not any(any(k in n for k in ['skin','camera']) for n in src['nodes'])
    start=len(blob);blob.extend(b);blob.extend(b'\0'*((-len(blob))%4))
    vi,ai,mi,ni,pi=(len(d[k]) for k in ['bufferViews','accessors','meshes','nodes','materials'])
    for old in src['bufferViews']:
      v=copy.deepcopy(old);assert v['buffer']==0;v['byteOffset']=v.get('byteOffset',0)+start;d['bufferViews'].append(v)
    for old in src['accessors']:
      a=copy.deepcopy(old);assert 'sparse' not in a;a['bufferView']+=vi;d['accessors'].append(a)
    d['materials'].extend(copy.deepcopy(src['materials']));assert d['materials'][pi:pi+len(src['materials'])]==src['materials']
    for old in src['meshes']:
      m=copy.deepcopy(old)
      for p in m['primitives']:
        assert p.get('mode',4)==4 and not p.get('targets');p['indices']+=ai;p['material']+=pi
        p['attributes']={k:v+ai for k,v in p['attributes'].items()}
      d['meshes'].append(m)
    for old in src['nodes']:
      n=copy.deepcopy(old);n['name']=key+'__'+n.get('name','node')
      if 'mesh'in n:n['mesh']+=mi
      if 'children'in n:n['children']=[x+ni for x in n['children']]
      d['nodes'].append(n)
    wrapper=len(d['nodes']);d['nodes'].append({'name':'INSTANCE__'+key,'matrix':wrapper_matrix(key),'children':[x+ni for x in src['scenes'][src.get('scene',0)]['nodes']]});d['nodes'][0]['children'].append(wrapper)
    proof[key]={'source_glb_sha256':hashlib.sha256(raw).hexdigest(),'original_meshes':len(src['meshes']),'original_payload_bytes_unchanged':True,'original_internal_TRS_and_matrix_unchanged':True,'unit_scale':True,'rotation_degrees':{(1,0):0,(0,1):90,(-1,0):180,(0,-1):270}[ROTATIONS[key]],'translation_zup_m':[f32(x)for x in OFFSETS[key]],'buffer_range':[start,start+len(b)]}
    assert bytes(blob[start:start+len(b)])==b


  meshes,materials=make_scene_structure();material_base=len(d['materials']);d['materials'].extend(materials)
  def array(values,component,kind):
    flat=[v for row in values for v in row] if kind=='VEC3' else values;fmt='f' if component==5126 else 'I'
    raw=struct.pack('<'+fmt*len(flat),*flat);offset=len(blob);blob.extend(raw);blob.extend(b'\0'*((-len(blob))%4));view=len(d['bufferViews']);d['bufferViews'].append({'buffer':0,'byteOffset':offset,'byteLength':len(raw)})
    a={'bufferView':view,'componentType':component,'count':len(values),'type':kind}
    if kind=='VEC3':a.update(min=[min(p[k]for p in values)for k in range(3)],max=[max(p[k]for p in values)for k in range(3)])
    index=len(d['accessors']);d['accessors'].append(a);return index


  for name,vertices,faces,mat in meshes:
   positions=[];normals=[]
   for ids in faces:
    tri=[vertices[i]for i in ids];a,b,c=tri;u=[b[k]-a[k]for k in range(3)];v=[c[k]-a[k]for k in range(3)];normal=(u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]);le=math.sqrt(sum(x*x for x in normal));assert le>1e-12;normal=[x/le for x in normal];positions.extend((x,z,-y)for x,y,z in tri);normals.extend([(normal[0],normal[2],-normal[1])]*3)
   primitive={'attributes':{'POSITION':array(positions,5126,'VEC3'),'NORMAL':array(normals,5126,'VEC3')},'indices':array(list(range(len(positions))),5125,'SCALAR'),'material':material_base+mat,'mode':4};mi=len(d['meshes']);d['meshes'].append({'name':name,'primitives':[primitive]});ni=len(d['nodes']);d['nodes'].append({'name':name,'mesh':mi,'extras':{'new_independent_model':False}});d['nodes'][0]['children'].append(ni)
  d['buffers']=[{'byteLength':len(blob)}];assert len(d['meshes'])==70 and len(d['materials'])==10
  proof['all_source_payloads_and_PBR_preserved']=all(v['original_payload_bytes_unchanged']for v in proof.values());proof['scene_only_meshes']=len(meshes);proof['triangles']=3888;proof['single_scene_count']=1;proof['new_independent_model_count']=0
  return d,bytes(blob),proof

def make_scene_structure():
 meshes=[]
 lo=(-1.625,-1.0625,0);hi=(1.625,1.0625,.0625);v=[(x,y,z)for z in[lo[2],hi[2]]for y in[lo[1],hi[1]]for x in[lo[0],hi[0]]];f=[]
 for a,b,c,d in[(0,2,3,1),(4,5,7,6),(0,1,5,4),(2,6,7,3),(0,4,6,2),(1,3,7,5)]:f.extend([(a,b,c),(a,c,d)])
 meshes.append(('SCENE_ONLY__WholeCommonFloor',v,f,0))
 p=[(.250,.0625),(.375,.0625),(.375,.4375),(1.250,.4375),(1.250,.0625),(1.375,.0625),(1.375,.5625),(.250,.5625)]
 def earclip(poly):
  cr=lambda a,b,c:(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);ids=list(range(len(poly)));out=[]
  while len(ids)>3:
   for j,b in enumerate(ids):
    a,c=ids[j-1],ids[(j+1)%len(ids)]
    if cr(poly[a],poly[b],poly[c])<=1e-12:continue
    if any(all(cr(poly[u],poly[w],poly[k])>=-1e-12 for u,w in[(a,b),(b,c),(c,a)])for k in ids if k not in[a,b,c]):continue
    out.append((a,b,c));ids.pop(j);break
   else:raise AssertionError('Invalid open bridge bench profile')
  out.append(tuple(ids));return out
 n=len(p);v=[(x,y,z)for y in[-.250,.625]for x,z in p];f=[]
 for a,b,c in earclip(p):f.extend([(a,b,c),(c+n,b+n,a+n)])
 for i in range(n):j=(i+1)%n;f.extend([(i,i+n,j+n),(i,j+n,j)])
 meshes.append(('SCENE_ONLY__WholeOpenBridgeBench',v,f,1))
 mats=[{'name':name,'doubleSided':True,'pbrMetallicRoughness':{'baseColorFactor':color,'metallicFactor':0.,'roughnessFactor':.91}}for name,color in [('SceneOnlyMatteCommonFloor',[.25,.28,.27,1]),('SceneOnlyWholeOpenBridgeBench',[.39,.35,.27,1])]]
 return meshes,mats

def main():
 import bpy,sys,time
 from mathutils import Vector
 OUT=Path(__file__).resolve().parent
 inputs={k:zlib.decompress(base64.b64decode(v['compressed']))for k,v in INPUTS.items()}
 for k,raw in inputs.items():assert hashlib.sha256(raw).hexdigest()==INPUTS[k]['sha256']
 for v in SOURCE_INPUTS.values():assert hashlib.sha256(zlib.decompress(base64.b64decode(v['compressed']))).hexdigest()==v['sha256']
 document,blob,proof=compose(inputs);model=pack_glb(document,blob);(OUT/'model.glb').write_bytes(model)
 bpy.ops.object.select_all(action='SELECT');bpy.ops.object.delete(use_global=False)
 bpy.ops.import_scene.gltf(filepath=str(OUT/'model.glb'))
 parts=[o for o in bpy.context.scene.objects if o.type=='MESH'];assert len(parts)==70
 triangle_count=sum(len(p.vertices)-2 for o in parts for p in o.data.polygons);assert triangle_count==proof['triangles']
 points=[o.matrix_world@v.co for o in parts for v in o.data.vertices]
 lo=[min(v[k]for v in points)for k in range(3)];hi=[max(v[k]for v in points)for k in range(3)]
 assert abs(lo[2])<=TOL and abs(lo[0]+hi[0])<=TOL and abs(lo[1]+hi[1])<=TOL
 assert len({m for o in parts for m in o.data.materials})==10
 component_checks=[]
 for o in parts:
  o.data.calc_loop_triangles();vv=[o.matrix_world@v.co for v in o.data.vertices];volume=sum(vv[t.vertices[0]].dot(vv[t.vertices[1]].cross(vv[t.vertices[2]]))/6 for t in o.data.loop_triangles);deg=sum(t.area<1e-12 for t in o.data.loop_triangles);assert deg==0 and volume>1e-10
  component_checks.append({'name':o.name,'triangles':len(o.data.loop_triangles),'signed_volume_m3':volume,'degenerate_triangles':deg})
 scene=bpy.context.scene;scene.render.engine='CYCLES';scene.cycles.samples=128;scene.cycles.use_adaptive_sampling=False;scene.cycles.use_denoising=False
 for layer in scene.view_layers:layer.cycles.use_denoising=False
 scene.use_nodes=False;scene.render.use_compositing=False;scene.render.threads_mode='FIXED';scene.render.threads=4
 scene.render.resolution_x=scene.render.resolution_y=640;scene.render.resolution_percentage=100
 # Save the formal complete asset-only native before any preview-only object is added.
 bpy.ops.wm.save_as_mainfile(filepath=str(OUT/'source.blend'),compress=False)
 scene.world=scene.world or bpy.data.worlds.new('Neutral whole impact tester and dual-column frame preparation bay');scene.world.use_nodes=True;scene.world.node_tree.nodes['Background'].inputs['Color'].default_value=(.3,.3,.3,1);scene.world.node_tree.nodes['Background'].inputs['Strength'].default_value=.8
 scene.view_settings.view_transform='AgX';focus=Vector((0.,0.,.95))
 def aim(o,pos):o.location=pos;o.rotation_euler=(focus-o.location).to_track_quat('-Z','Y').to_euler()
 for name,pos,power,size in [('Key',(-8,-10,14),2200,9),('Fill',(10,-6,10),1500,8),('Rim',(4,12,12),1800,8)]:
  bpy.ops.object.light_add(type='AREA',location=pos);o=bpy.context.object;o.name='Preview_'+name;o.data.energy=power;o.data.shape='DISK';o.data.size=size;aim(o,pos)
 bpy.ops.object.camera_add();cam=bpy.context.object;cam.name='Preview_Camera';cam.data.type='ORTHO';scene.camera=cam;aim(cam,(3.5,-7.5,4.4));bpy.context.view_layer.update()
 rot=cam.rotation_euler.to_quaternion();right=rot@Vector((1,0,0));up=rot@Vector((0,1,0));xx=[v.dot(right)for v in points];yy=[v.dot(up)for v in points]
 cam.location+=right*((min(xx)+max(xx))/2-cam.location.dot(right))+up*((min(yy)+max(yy))/2-cam.location.dot(up));cam.data.ortho_scale=max(max(xx)-min(xx),max(yy)-min(yy))*1.12
 bpy.ops.mesh.primitive_plane_add(size=200,location=(0,0,-.0003));ground=bpy.context.object;ground.name='Preview_ground_not_asset';mat=bpy.data.materials.new('Preview_slate');mat.diffuse_color=(.20,.24,.25,1);ground.data.materials.append(mat)
 def config():return dict(engine=scene.render.engine,samples=scene.cycles.samples,adaptive=scene.cycles.use_adaptive_sampling,cycles_denoise=scene.cycles.use_denoising,view_layer_denoise=[x.cycles.use_denoising for x in scene.view_layers],compositor_nodes=scene.use_nodes,compositing=scene.render.use_compositing,threads_mode=scene.render.threads_mode,threads=scene.render.threads)
 qa={'review_mode':'SELF_REVIEW','status':'GEOMETRY_CREATED_NEEDS_MAKER_REVIEW','asset_id':ASSET,'asset':ASSET,'source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'glb_sha256':hashlib.sha256(model).hexdigest(),'mesh_count':70,'mesh_objects':70,'triangles':triangle_count,'materials':10,'bounds_min_m':lo,'bounds_max_m':hi,'composition':proof,'native_readback_claim':False,'normal_setter_or_vertex_bake_used':False,'render_configuration':{'samples':128,'threads':4,'engine':'CYCLES','denoising':False}}
 qa['components']=component_checks;qa['actual_glb_sha256']=hashlib.sha256(model).hexdigest();qa['new_model_count']=0;qa['new_scene_count']=1;qa['native_saved_render_config']=config();qa['render_configs']={}
 if '--geometry-only' not in sys.argv:
  view=sys.argv[sys.argv.index('--tier-single-view')+1]if '--tier-single-view'in sys.argv else 'thumbnail';assert view in ['qa-front','thumbnail']
  scene.cycles.samples=16 if view=='qa-front' else 128;qa['render_configs'][view]=config();scene.render.filepath=str(OUT/(view+'.png'));start=time.monotonic();bpy.ops.render.render(write_still=True);qa['render']={'view':view,'samples':scene.cycles.samples,'seconds':time.monotonic()-start,'original_pixels_reviewed':False}
 (OUT/'qa-report.json').write_text(json.dumps(qa,indent=2)+'\n')
 files={}
 for role,name in [('glb','model.glb'),('blend','source.blend'),('generator','generate.py'),('render','thumbnail.png')]:
  p=OUT/name
  if p.exists():files[role]={'path':f'assets/industrial/{ASSET}/v1.0.0/{name}','size':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
 if len(files)==4:
  meta={'id':ASSET,'version':'1.0.0','category':'scenes','assetKind':'scene','theme':'industrial','style':'source-preserved-low-poly','title':TITLE,'description':DESCRIPTION,'bounds':dict(zip(['x','y','z'],[hi[k]-lo[k]for k in range(3)]),unit='m'),'triangles':triangle_count,'materials':10,'files':files,'status':'review','license':'All rights reserved'}
  (OUT/'metadata.json').write_text(json.dumps(meta,indent=2)+'\n')
 print('SCENE_STAGE_COMPLETE',ASSET,triangle_count)

if __name__=='__main__':main()
